import { useState } from "react";

function App() {
  const [text, setText] = useState("");
  const [cvText, setCvText] = useState("");
  const [result, setResult] = useState(null);
  const [loading, setLoading] = useState(false);
  const [history, setHistory] = useState([]);

  const handleExtract = async () => {
    if (!text) return;

    setLoading(true);

    try {
      const response = await fetch("http://127.0.0.1:8000/extract", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify({
          job_description: text,
          cv: cvText,
        }),
      });

      const data = await response.json();
      setResult(data);

      setHistory((prev) => [
        { text: text.slice(0, 50) + "...", data },
        ...prev,
      ]);
    } catch (error) {
      console.error(error);
    }

    setLoading(false);
  };

  const isLimited = result?.skills?.includes("LIMIT REACHED");
  const score = result?.score || 0;

  return (
    <div className="min-h-screen bg-slate-950 text-white flex">

      {/* SIDEBAR */}
      <div className="w-64 bg-slate-900 border-r border-slate-800 p-4 hidden md:block">
        <h2 className="text-lg font-semibold mb-4">History</h2>

        <div className="space-y-2">
          {history.length === 0 && (
            <p className="text-gray-500 text-sm">No history yet</p>
          )}

          {history.map((item, index) => (
            <div
              key={index}
              onClick={() => setResult(item.data)}
              className="cursor-pointer p-2 bg-slate-800 hover:bg-slate-700 rounded-lg text-sm"
            >
              {item.text}
            </div>
          ))}
        </div>
      </div>

      {/* MAIN */}
      <div className="flex-1 p-6">

        {/* NAVBAR */}
        <div className="flex justify-between items-center mb-6">
          <div className="flex items-center gap-3">
            <div className="w-10 h-10 bg-gradient-to-br from-indigo-500 to-purple-600 rounded-xl flex items-center justify-center font-bold">
              AI
            </div>
            <span className="text-xl font-semibold">AI Job Match Analyzer</span>
          </div>

          <button
            onClick={() => window.open("https://your-payment-link.com", "_blank")}
            className="px-4 py-2 bg-green-500 hover:bg-green-600 rounded-lg"
          >
            Unlock Full Analysis
          </button>
        </div>

        <div className="grid md:grid-cols-2 gap-6">

          {/* INPUT PANEL */}
          <div className="bg-slate-900 p-6 rounded-2xl border border-slate-800">
            <h2 className="text-xl font-semibold mb-2">Analyze Job</h2>

            <textarea
              className="w-full h-40 p-4 rounded-xl bg-slate-950 border border-slate-700 focus:ring-2 focus:ring-indigo-500"
              placeholder="Paste job description..."
              value={text}
              onChange={(e) => setText(e.target.value)}
            />

            <textarea
              className="w-full h-32 mt-4 p-4 rounded-xl bg-slate-950 border border-slate-700 focus:ring-2 focus:ring-indigo-500"
              placeholder="Paste your CV / skills (optional)..."
              value={cvText}
              onChange={(e) => setCvText(e.target.value)}
            />

            <button
              onClick={handleExtract}
              className="w-full mt-4 py-3 rounded-xl bg-gradient-to-r from-indigo-500 to-purple-600 font-semibold shadow-lg"
            >
              {loading ? "Analyzing..." : "Analyze Job Match"}
            </button>

            <p className="text-xs text-gray-500 mt-3 text-center">
              Get a personalized breakdown of your job fit
            </p>
          </div>

          {/* RESULTS PANEL */}
          <div className="bg-slate-900 p-6 rounded-2xl border border-slate-800 space-y-6">

            {!result && (
              <p className="text-gray-500 text-center">Results appear here</p>
            )}

            {result && (
              <>
                {/* SCORE */}
                <div className="bg-slate-950 p-4 rounded-xl border border-slate-700">
                  <p className="text-sm text-gray-400">Match Score</p>
                  <p className="text-3xl font-bold text-indigo-400">{score}%</p>
                </div>

                {/* CORE SKILLS */}
                <Section title="Core Skills" items={result.core_skills} highlight />

                {/* ALL SKILLS */}
                <Section title="All Skills" items={result.skills} />

                {/* MISSING SKILLS */}
                <div>
                  <h3 className="text-lg font-semibold mb-2">Missing Skills</h3>

                  {isLimited ? (
                    <Locked />
                  ) : (
                    <Section items={result.missing_skills} />
                  )}
                </div>

                {/* ROADMAP */}
                <div>
                  <h3 className="text-lg font-semibold mb-2">Learning Roadmap</h3>

                  {isLimited ? (
                    <Locked />
                  ) : (
                    <ul className="list-disc list-inside text-gray-300 space-y-1">
                      {result.missing_skills?.slice(0, 5).map((s, i) => (
                        <li key={i}>
                          Week {i + 1}: Learn {s}
                        </li>
                      ))}
                    </ul>
                  )}
                </div>

                {/* LEVEL */}
                <div className="bg-slate-950 p-4 rounded-xl border border-slate-700">
                  <p className="text-sm text-gray-400">Experience Level</p>
                  <p className="text-indigo-400 font-semibold">{result.level}</p>
                </div>
              </>
            )}
          </div>
        </div>
      </div>
    </div>
  );
}

function Section({ title, items = [], highlight }) {
  return (
    <div>
      {title && <h3 className="text-lg font-semibold mb-2">{title}</h3>}
      <div className="flex flex-wrap gap-2">
        {(items || []).map((item, i) => (
          <span
            key={i}
            className={`px-3 py-1 rounded-full text-sm ${
              highlight ? "bg-indigo-500" : "bg-slate-700"
            }`}
          >
            {item}
          </span>
        ))}
      </div>
    </div>
  );
}

function Locked() {
  return (
    <div className="relative">
      <div className="blur-sm">
        <ul className="list-disc list-inside text-gray-500">
          <li>Docker</li>
          <li>AWS</li>
          <li>System Design</li>
        </ul>
      </div>

      <div className="absolute inset-0 flex flex-col items-center justify-center">
        <p className="text-sm mb-2">🔒 Unlock Full Analysis</p>
        <button className="px-4 py-2 bg-green-500 rounded-lg">
          Get Full Report
        </button>
      </div>
    </div>
  );
}

export default App;
